package io.github.diodeme.ji.agent.core;

import io.github.diodeme.ji.extension.PromptTemplateRenderer;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Map;
import java.util.Set;

final class BuiltinPromptTemplates {
    private static final String ROOT = "/io/github/diodeme/ji/agent/core/prompts/v1/";
    private static final PromptTemplateRenderer RENDERER = new PromptTemplateRenderer();
    private static final List<PromptTemplateRenderer.Template> TEMPLATES = List.of(
            load("system", "en", Set.of("workingDirectory", "toolGuidelines", "context", "skills")),
            load("system", "zh-CN", Set.of("workingDirectory", "toolGuidelines", "context", "skills")),
            load("repair", "en", Set.of("operation", "failure", "retryContext")),
            load("repair", "zh-CN", Set.of("operation", "failure", "retryContext")));

    static {
        RENDERER.verifyLocaleSymmetry(TEMPLATES, Set.of("en", "zh-CN"));
    }

    private BuiltinPromptTemplates() {}

    static String system(String locale, Map<String, String> variables) {
        return RENDERER.render(find("system", locale), variables).text();
    }

    static List<PromptTemplateRenderer.Template> templates() {
        return TEMPLATES;
    }

    private static PromptTemplateRenderer.Template find(String id, String locale) {
        return TEMPLATES.stream().filter(value -> value.id().equals(id) && value.locale().equals(locale))
                .findFirst().orElseThrow(() -> new IllegalArgumentException("unsupported prompt locale: " + locale));
    }

    private static PromptTemplateRenderer.Template load(String id, String locale, Set<String> variables) {
        String path = ROOT + locale + "/" + id + ".md";
        try (var stream = BuiltinPromptTemplates.class.getResourceAsStream(path)) {
            if (stream == null) throw new IllegalStateException("missing built-in prompt: " + path);
            return new PromptTemplateRenderer.Template(id, locale,
                    new String(stream.readAllBytes(), StandardCharsets.UTF_8), variables);
        } catch (IOException failure) {
            throw new IllegalStateException("cannot load built-in prompt: " + path, failure);
        }
    }
}

